// Generates data/rework_trees.gd (the reworked towers' trees as game data) from design/balance.md (the numbers and prices,
// the balance master, issue #75) and design/upgrade_trees_rework.md (names and blurbs). Run: node tools/tree_rework_data.mjs
// (from the project folder), after node tools/balance.mjs. Add --check to exit non-zero if the generated file on disk is
// stale (tools/dev.sh check does).
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { join } from "node:path";
import { root, BALANCE, TREES, read, parseTowers, parseTrees } from "./balance_lib.mjs";

const out = join(root, "data", "rework_trees.gd");
const errors = [];
const fail = (m) => errors.push(m);
const statTowers = parseTowers(read(BALANCE), errors);
const designTowers = parseTrees(read(TREES));

// --- emit
const q = (s) => JSON.stringify(String(s));
const num = (v) => (Number.isInteger(v) ? v.toFixed(1) : String(v));
const val = (v) => (v === true ? "true" : num(v));
const dict = (o, ind) => {
  const keys = Object.keys(o);
  if (!keys.length) return "{}";
  return "{\n" + keys.map((k) => `${ind}\t${q(k)}: ${val(o[k])},`).join("\n") + `\n${ind}}`;
};
const node = (r, st, ind) => {
  const n = st.nodes[r.id] || { set: {}, add: {}, cost: 0 };
  return `{\n${ind}\t"name": ${q(r.name)},\n${ind}\t"cost": ${n.cost},\n${ind}\t"blurb": ${q(r.effect)},\n${ind}\t"set": ${dict(n.set, ind + "\t")},\n${ind}\t"add": ${dict(n.add, ind + "\t")},\n${ind}}`;
};
let body = "";
const order = [];
for (const slug of Object.keys(statTowers)) {
  const st = statTowers[slug], d = designTowers[slug];
  if (!d) { fail(`${slug}: not in upgrade_trees_rework.md`); continue; }
  order.push(slug);
  const rows = d.rows;
  const byId = Object.fromEntries(rows.map((r) => [r.id, r]));
  for (const id of Object.keys(st.nodes)) if (!byId[id]) fail(`${slug}: node ${id} isn't in the design`);
  for (const r of rows) if (!st.nodes[r.id]) fail(`${slug}: node ${r.id} (${r.name}) has no stats`);
  const retro = rows.filter((r) => /^r\d$/.test(r.id));
  const ind = "\t\t";
  body += `\t${q(slug)}: {\n\t\t"name": ${q(d.name)},\n\t\t"class": ${q(d.cls)},\n\t\t"weapon": ${q(d.weapon)},\n\t\t"blurb": ${q(d.blurb)},\n`;
  body += `\t\t"air": ${st.meta.air === "yes"},\n\t\t"ground": ${st.meta.ground === "yes"},\n\t\t"size": ${parseInt(st.meta.size, 10)},\n\t\t"damage_kind": ${q(st.meta.damage_kind || "physical")},\n\t\t"beam": ${st.meta.beam === "yes"},\n\t\t"uncapped": ${st.meta.uncapped === "yes"},\n\t\t"support": ${st.meta.support === "yes"},\n\t\t"economy": ${st.meta.economy === "yes"},\n`;
  body += `\t\t"cost": ${st.nodes.base.cost},\n\t\t"base": ${node(byId.base, st, ind)},\n\t\t"retrofits": [\n${retro.map((r) => `\t\t\t${node(r, st, "\t\t\t")},`).join("\n")}\n\t\t],\n\t\t"paths": [\n`;
  "abc".split("").forEach((k, i) => {
    body += `\t\t\t{\n\t\t\t\t"key": ${q(k)},\n\t\t\t\t"name": ${q(d.branches[i])},\n\t\t\t\t"nodes": [\n`;
    for (let s = 1; s <= 4; s++) body += `\t\t\t\t\t${node(byId[k + s], st, "\t\t\t\t\t")},\n`;
    body += `\t\t\t\t],\n\t\t\t\t"mastery": ${node(byId[k + "m"], st, "\t\t\t\t")},\n\t\t\t},\n`;
  });
  body += "\t\t],\n\t},\n";
}
const text = `extends RefCounted
## GENERATED by tools/tree_rework_data.mjs from design/balance.md (numbers and prices) and design/upgrade_trees_rework.md
## (names and blurbs). Edit those and re-run the generator; don't edit this file by hand.
##
## The reworked towers (issue #59). Per tower: \`base\`, \`retrofits\` (the player picks one of up to three), and \`paths\`
## (a, b, c), each with four \`nodes\` and a \`mastery\`. A node's \`add\` values add to the stat and its \`set\` values replace it
## (upgrades only set flags; issue #85); nodes apply in order on top of the base (the Retrofit, then each path's steps).

const ORDER := [${order.map(q).join(", ")}]

static var TREES := {
${body}}
`;
if (errors.length) { console.error(errors.join("\n")); process.exit(1); }
if (process.argv.includes("--check")) {
  const cur = existsSync(out) ? readFileSync(out, "utf8").replace(/\r\n/g, "\n") : "";
  if (cur !== text) { console.error("data/rework_trees.gd is stale: run node tools/tree_rework_data.mjs"); process.exit(1); }
  console.log("rework_trees.gd is current");
} else {
  writeFileSync(out, text);
  console.log(`wrote data/rework_trees.gd (${order.length} tower${order.length === 1 ? "" : "s"})`);
}
